# Additional common entries; all values remain approximate per 100 g edible portion.
def _food(name: str, kcal: float, protein: float, fat: float, carbs: float, fiber: float = 0.0) -> dict[str, Any]:
    return {"name": name, "kcal": kcal, "kj": round(kcal * 4.184), "protein": protein, "fat": fat, "carbs": carbs, "fiber": fiber, "he": round(carbs / 12.0, 2)}

