def convert_measurement(value: float, from_unit: str, to_unit: str) -> dict[str, Any]:
    index = {item["id"]: item for item in MEASURE_UNITS}
    if from_unit not in index or to_unit not in index:
        raise ValueError("Неизвестная единица измерения")
    src, dst = index[from_unit], index[to_unit]
    if src["group"] != dst["group"]:
        raise ValueError("Единицы относятся к разным физическим величинам")
    x = float(value)
    base_value = x * float(src["scale"]) + float(src["offset"])
    if src["group"] == "Температура" and base_value < 0:
        raise ValueError("Температура ниже абсолютного нуля невозможна")
    result = (base_value - float(dst["offset"])) / float(dst["scale"])
    if not math.isfinite(result):
        raise ValueError("Результат вне допустимого диапазона")
    return {"value": x, "from": src, "to": dst, "result": result}


