def get_recipes(q: str = "", category: str = "") -> list[dict[str, Any]]:
    term, cat = q.strip().casefold(), category.strip().casefold()
    return [r for r in RECIPE_BOOK if (not term or term in r["name"].casefold() or any(term in t.casefold() for t in r["tags"]) or any(term in item["name"].casefold() for item in r["ingredients"])) and (not cat or r["category"].casefold() == cat)]


def scale_recipe(recipe_id: str, servings: float = 1.0) -> dict[str, Any]:
    recipe = next((r for r in RECIPE_BOOK if r["id"] == recipe_id), None)
    if recipe is None:
        raise ValueError("Рецепт не найден")
    servings = float(servings)
    if not math.isfinite(servings) or not 0.25 <= servings <= 20:
        raise ValueError("Количество порций должно быть от 0.25 до 20")
    factor = servings / recipe["servings"]
    foods = {f["name"]: f for f in FOOD_DB}
    ingredients = []
    nutrition = {key: 0.0 for key in ("kcal", "kj", "protein_g", "fat_g", "carbs_g", "fiber_g", "bread_units")}
    fields = {"kcal":"kcal", "kj":"kj", "protein_g":"protein", "fat_g":"fat", "carbs_g":"carbs", "fiber_g":"fiber", "bread_units":"he"}
    for ingredient in recipe["ingredients"]:
        grams = ingredient["grams"] * factor
        ingredients.append({"name": ingredient["name"], "grams": round(grams, 1)})
        food = foods.get(ingredient["name"])
        if food:
            for output, source in fields.items():
                nutrition[output] += float(food[source]) * grams / 100
    return {"recipe": recipe, "servings": servings, "ingredients": ingredients, "nutrition": {k: round(v, 1 if k != "bread_units" else 2) for k, v in nutrition.items()}, "note": "Оценка включает только перечисленные продукты; масло, соль, соусы и потеря/набор воды могут менять результат."}


