def calculate_nutrition(food: dict[str, Any], grams: float) -> dict[str, Any]:
    grams = max(0.0, min(10000.0, float(grams)))
    scale = grams / 100.0
    return {"food": food["name"], "grams": round(grams, 1), "kcal": round(food["kcal"] * scale, 1), "kj": round(food["kj"] * scale, 1), "protein_g": round(food["protein"] * scale, 1), "fat_g": round(food["fat"] * scale, 1), "carbs_g": round(food["carbs"] * scale, 1), "fiber_g": round(food["fiber"] * scale, 1), "bread_units": round(food["he"] * scale, 2), "reference": "Ориентировочные усреднённые значения на 100 г; рецепт, сорт и обработка меняют состав. 1 ХЕ здесь условно 12 г усвояемых углеводов."}


def calculate_sleep_windows(wake_time: str, latency_min: int = 15) -> dict[str, Any]:
    from datetime import datetime, timedelta
    try:
        wake = datetime.strptime(wake_time, "%H:%M")
    except ValueError as exc:
        raise ValueError("Время укажите в формате ЧЧ:ММ") from exc
    latency = max(0, min(120, int(latency_min)))
    options = []
    for cycles in (4, 5, 6):
        bed = wake - timedelta(minutes=cycles * 90 + latency)
        options.append({"cycles": cycles, "bedtime": bed.strftime("%H:%M"), "sleep_hours": cycles * 1.5, "note": "Цикл 90 минут — упрощённое приближение, не индивидуальный прогноз."})
    return {"wake_time": wake_time, "options": options, "note": "Для большинства взрослых ориентир — регулярно не менее 7 часов сна; индивидуальная потребность различается. Это планировщик, не медицинская рекомендация."}


def calculate_flower_bouquet(
    stems: list[dict[str, Any]], wrapping: float = 0.0, labor: float = 0.0,
    markup_pct: float = 0.0, currency: str = "RUB",
) -> dict[str, Any]:
    allowed_currencies = {"RUB", "EUR", "USD", "GBP", "KZT"}
    code = str(currency).upper()
    if code not in allowed_currencies:
        raise ValueError("Валюта должна быть одной из RUB, EUR, USD, GBP или KZT")

    def bounded_number(value: Any, label: str, minimum: float, maximum: float) -> float:
        try:
            number = float(value)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"{label}: введите число") from exc
        if not math.isfinite(number) or not minimum <= number <= maximum:
            raise ValueError(f"{label}: допустимый диапазон {minimum:g}–{maximum:g}")
        return number

    wrap_cost = bounded_number(wrapping, "Упаковка", 0, 100000)
    labor_cost = bounded_number(labor, "Работа", 0, 100000)
    markup = bounded_number(markup_pct, "Наценка", 0, 300)
    normalized: list[dict[str, Any]] = []
    total = 0.0
    for index, row in enumerate(stems[:30], start=1):
        count_value = bounded_number(row.get("count", 0), f"Количество в строке {index}", 0, 300)
        if not count_value.is_integer():
            raise ValueError(f"Количество в строке {index} должно быть целым")
        count = int(count_value)
        price = bounded_number(row.get("price", 0), f"Цена в строке {index}", 0, 100000)
        name = str(row.get("name", "")).strip()[:40] or f"Позиция {index}"
        line = round(count * price, 2)
        normalized.append({"name": name, "count": count, "unit_price": price, "line_total": line})
        total += line

    direct = total + wrap_cost + labor_cost
    suggested = direct * (1 + markup / 100)
    return {
        "items": normalized,
        "flowers": round(total, 2),
        "wrapping": round(wrap_cost, 2),
        "labor": round(labor_cost, 2),
        "subtotal": round(direct, 2),
        "markup_pct": round(markup, 2),
        "markup_amount": round(suggested - direct, 2),
        "suggested_price": round(suggested, 2),
        "currency": code,
        "note": "Примерная калькуляция по введённым ценам. Наценка применяется к прямым затратам; прибыль до прочих расходов, налогов и доставки может отличаться.",
    }


